CREATE OR REPLACE FUNCTION public.app_admin_cancel_user_invitation(p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_admin_role TEXT;
    v_updated_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_admin_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_admin_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    UPDATE app.user_invitations
    SET status = 'cancelled',
        updated_at = NOW()
    WHERE id = p_invitation_id
      AND status = 'pending'
    RETURNING id INTO v_updated_id;

    IF v_updated_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invitation_not_found_or_not_pending');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'invitation_id', v_updated_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_create_user_invitation(p_email text, p_role text, p_university_id uuid DEFAULT NULL::uuid, p_full_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_admin_role TEXT;
    v_token TEXT;
    v_id UUID;
    v_lower_email TEXT;
    v_target_role TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_admin_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_admin_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF p_email IS NULL OR LENGTH(TRIM(p_email)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_email');
    END IF;

    v_lower_email := LOWER(TRIM(p_email));

    IF p_role IS NULL OR LENGTH(TRIM(p_role)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_role');
    END IF;

    v_target_role := TRIM(p_role);

    IF v_target_role NOT IN ('admin', 'university', 'instructor') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'unsupported_role');
    END IF;

    IF v_target_role = 'university' AND p_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_required');
    END IF;

    v_token := encode(gen_random_bytes(16), 'hex');

    INSERT INTO app.user_invitations (
        token,
        email,
        role,
        university_id,
        full_name,
        notes,
        status,
        created_by_admin_id,
        created_at,
        used_at,
        expires_at,
        updated_at
    )
    VALUES (
        v_token,
        v_lower_email,
        v_target_role,
        p_university_id,
        p_full_name,
        p_notes,
        'pending',
        v_user_id,
        NOW(),
        NULL,
        p_expires_at,
        NOW()
    )
    RETURNING id INTO v_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'invitation_id', v_id,
        'token', v_token
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_delete_user_account(p_target_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_target_exists BOOLEAN;
  v_target_role TEXT;
  v_target_university_id UUID;
  v_other_admins_count INTEGER;
  v_is_deleted BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
  END IF;

  SELECT raw_user_meta_data->>'role'
  INTO v_role
  FROM auth.users
  WHERE id = v_user_id;

  IF v_role <> 'admin' THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
  END IF;

  IF p_target_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_target_user_id');
  END IF;

  IF p_target_user_id = v_user_id THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'cannot_delete_self');
  END IF;

  SELECT EXISTS (SELECT 1 FROM auth.users WHERE id = p_target_user_id)
  INTO v_target_exists;

  IF NOT v_target_exists THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'user_not_found');
  END IF;

  SELECT
    raw_user_meta_data->>'role',
    (raw_user_meta_data->>'university_id')::UUID
  INTO v_target_role, v_target_university_id
  FROM auth.users
  WHERE id = p_target_user_id;

  IF v_target_role = 'admin' THEN
    SELECT COUNT(*)
    INTO v_other_admins_count
    FROM auth.users u
    WHERE u.raw_user_meta_data->>'role' = 'admin'
      AND u.id <> p_target_user_id;

    IF v_other_admins_count = 0 THEN
      RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'cannot_delete_last_admin');
    END IF;
  END IF;

  -- Si on supprime un compte université, désactiver aussi l'université associée
  -- afin que ses offres et sa fiche disparaissent des vues côté étudiant.
  IF v_target_role = 'university' AND v_target_university_id IS NOT NULL THEN
    PERFORM app_admin_update_university_status(
      v_target_university_id,
      FALSE,
      COALESCE(p_reason, 'university_account_deleted')
    );
  END IF;

  INSERT INTO app.user_admin_status (
    user_id,
    is_suspended,
    suspended_reason,
    suspended_at,
    reactivated_at,
    updated_at,
    is_deleted,
    deleted_reason,
    deleted_at
  ) VALUES (
    p_target_user_id,
    TRUE,
    COALESCE(p_reason, 'account_deleted'),
    NOW(),
    NULL,
    NOW(),
    TRUE,
    p_reason,
    NOW()
  )
  ON CONFLICT (user_id)
  DO UPDATE SET
    is_suspended = TRUE,
    suspended_reason = COALESCE(EXCLUDED.suspended_reason, app.user_admin_status.suspended_reason),
    suspended_at = COALESCE(app.user_admin_status.suspended_at, NOW()),
    reactivated_at = NULL,
    updated_at = NOW(),
    is_deleted = TRUE,
    deleted_reason = COALESCE(EXCLUDED.deleted_reason, app.user_admin_status.deleted_reason),
    deleted_at = COALESCE(app.user_admin_status.deleted_at, NOW());

  v_is_deleted := TRUE;

  INSERT INTO app.admin_user_action_logs (
    performed_by,
    target_user,
    action,
    reason,
    meta
  ) VALUES (
    v_user_id,
    p_target_user_id,
    'delete',
    p_reason,
    JSONB_BUILD_OBJECT(
      'is_deleted', v_is_deleted,
      'performed_by', v_user_id,
      'target_user', p_target_user_id
    )
  );

  RETURN JSONB_BUILD_OBJECT(
    'success', TRUE,
    'user_id', p_target_user_id,
    'action', 'delete',
    'is_deleted', v_is_deleted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_list_user_invitations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_admin_role TEXT;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_admin_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_admin_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', i.id,
                'token', i.token,
                'email', i.email,
                'role', i.role,
                'university_id', i.university_id,
                'full_name', i.full_name,
                'notes', i.notes,
                'status', i.status,
                'created_by_admin_id', i.created_by_admin_id,
                'created_at', i.created_at,
                'used_at', i.used_at,
                'expires_at', i.expires_at,
                'updated_at', i.updated_at
            )
            ORDER BY i.created_at DESC
        ),
        '[]'::JSONB
    ) INTO v_result
    FROM app.user_invitations i;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'invitations', v_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_set_commercial_commission_rate(p_user_id uuid, p_rate numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_existing app.commercial_profiles%ROWTYPE;
  v_ref_code TEXT;
  v_base_url TEXT;
BEGIN
  -- Base publique de l'app : configurable via le paramètre Postgres
  --   app.app_public_base_url
  -- avec repli sur l'URL Netlify actuelle.
  v_base_url := COALESCE(
    current_setting('app.app_public_base_url', true),
    'https://dulcet-snickerdoodle-915a6b.netlify.app'
  );
  IF v_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
  END IF;

  SELECT raw_user_meta_data->>'role'
  INTO v_role
  FROM auth.users
  WHERE id = v_user_id;

  IF v_role <> 'admin' THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
  END IF;

  IF p_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_user_id');
  END IF;

  IF p_rate IS NULL OR p_rate < 0 THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_rate');
  END IF;

  SELECT *
  INTO v_existing
  FROM app.commercial_profiles
  WHERE user_id = p_user_id;

  IF NOT FOUND THEN
    -- Générer un ref_code simple basé sur un UUID tronqué
    v_ref_code := 'COMM-' || SUBSTR(REPLACE(gen_random_uuid()::TEXT, '-', ''), 1, 8);

    INSERT INTO app.commercial_profiles (
      user_id,
      ref_code,
      ref_link,
      commission_rate,
      is_active,
      created_at,
      updated_at
    ) VALUES (
      p_user_id,
      v_ref_code,
      v_base_url || '/?ref=' || v_ref_code,
      p_rate,
      TRUE,
      NOW(),
      NOW()
    );
  ELSE
    -- Conserver le ref_code existant si présent, sinon en générer un nouveau
    IF v_existing.ref_code IS NULL OR TRIM(v_existing.ref_code) = '' THEN
      v_ref_code := 'COMM-' || SUBSTR(REPLACE(gen_random_uuid()::TEXT, '-', ''), 1, 8);
    ELSE
      v_ref_code := v_existing.ref_code;
    END IF;

    UPDATE app.commercial_profiles
    SET
      ref_code = v_ref_code,
      ref_link = v_base_url || '/?ref=' || v_ref_code,
      commission_rate = p_rate,
      updated_at = NOW()
    WHERE user_id = p_user_id;
  END IF;

  RETURN JSONB_BUILD_OBJECT('success', TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_update_referral_commission_status(p_commission_id uuid, p_new_status text, p_admin_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_comm app.referral_commissions%ROWTYPE;
  v_now TIMESTAMPTZ := NOW();
  v_final_status TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
  END IF;

  SELECT raw_user_meta_data->>'role'
  INTO v_role
  FROM auth.users
  WHERE id = v_user_id;

  IF v_role <> 'admin' THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
  END IF;

  IF p_commission_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_commission_id');
  END IF;

  IF p_new_status IS NULL OR LENGTH(TRIM(p_new_status)) = 0 THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_status');
  END IF;

  v_final_status := LOWER(TRIM(p_new_status));

  IF v_final_status NOT IN ('pending', 'approved', 'paid', 'rejected') THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'unsupported_status');
  END IF;

  SELECT *
  INTO v_comm
  FROM app.referral_commissions
  WHERE id = p_commission_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'commission_not_found');
  END IF;

  -- Empêcher de modifier une commission déjà payée ou rejetée
  IF v_comm.status IN ('paid', 'rejected') THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'status_immutable');
  END IF;

  -- Autoriser :
  -- pending -> approved / paid / rejected
  -- approved -> paid / rejected
  IF v_comm.status = 'pending' THEN
    IF v_final_status NOT IN ('approved', 'paid', 'rejected') THEN
      RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_transition');
    END IF;
  ELSIF v_comm.status = 'approved' THEN
    IF v_final_status NOT IN ('paid', 'rejected') THEN
      RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_transition');
    END IF;
  ELSE
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_transition');
  END IF;

  UPDATE app.referral_commissions
  SET
    status = v_final_status,
    approved_at = CASE
      WHEN v_final_status IN ('approved', 'paid') AND approved_at IS NULL
        THEN v_now
      ELSE approved_at
    END,
    paid_at = CASE
      WHEN v_final_status = 'paid' THEN v_now
      ELSE paid_at
    END,
    admin_note = COALESCE(p_admin_note, admin_note)
  WHERE id = p_commission_id;

  -- Notification quand la commission est marquée comme payée
  IF v_final_status = 'paid' THEN
    BEGIN
      PERFORM app_queue_notification_event(
        v_comm.commercial_user_id,
        'commercial_commissions',
        'commission_paid',
        JSONB_BUILD_OBJECT(
          'commission_id', v_comm.id,
          'student_id', v_comm.student_id,
          'payment_id', v_comm.payment_id,
          'commission_amount', v_comm.commission_amount,
          'currency', v_comm.currency
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN JSONB_BUILD_OBJECT('success', TRUE, 'new_status', v_final_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_update_university_status(p_university_id uuid, p_is_active boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_university_id UUID;
    v_university_exists BOOLEAN;
    v_target_user_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF p_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_university_id');
    END IF;

    SELECT id
    INTO v_university_id
    FROM app.universities
    WHERE id = p_university_id;

    IF v_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_not_found');
    END IF;

    UPDATE app.universities
    SET is_active = COALESCE(p_is_active, is_active),
        updated_at = NOW()
    WHERE id = v_university_id;

    IF p_is_active IS FALSE THEN
        FOR v_target_user_id IN
            SELECT u.id
            FROM auth.users u
            WHERE u.raw_user_meta_data->>'role' = 'university'
              AND (u.raw_user_meta_data->>'university_id')::UUID = v_university_id
        LOOP
            PERFORM app_admin_update_user_status(
                v_target_user_id,
                'suspend',
                COALESCE(p_reason, 'university_deactivated')
            );
        END LOOP;
    END IF;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'university_id', v_university_id,
        'is_active', p_is_active
    );
END;
$function$
